import logging
import time
import re
from collections import namedtuple
from openstack.cloud.exc import OpenStackCloudException
from openstack.image.v2.image import Image as OpenstackImage
from openstack.exceptions import SDKException
from typing import Optional, Union, List  # noqa: F401
from taf.config.testline.cloud_hosting import DeploymentVnfStack  # noqa: F401
from taf.cloud.openstack.exceptions import OSSDKException
from taf.cloud.openstack.exceptions import ImageNotFound
from taf.cloud.openstack.exceptions import Timeout
from taf.cloud.openstack.exceptions import UploadFail
from taf.cloud.openstack.connection import verify_connection
from taf.cloud.openstack.configuration import ConfigurationModifier
from taf.cloud.openstack.stack_environment_store import PreparedEnvironments
from taf.cloud.openstack.yaml_helper import save_dict_as_yaml


ImageData = namedtuple('ImageData', ['status', 'id', 'name'])


class ImageStatus(object):
    DELETED = 'deleted'
    QUEUED = 'queued'
    SAVING = 'saving'
    ACTIVE = 'active'
    DEACTIVATED = 'deactivated'
    KILLED = 'killed'
    PENDING_DELETE = 'pending_delete'


class Image(object):
    IMAGE_STATUS_SUCCESS = "success"
    CHECK_INTERVAL = 2
    IMAGE_VISIBILITY = 'public'
    DEFAULT_DISK_FORMAT = "qcow2"

    def __init__(self, connection):
        verify_connection(connection)
        self.connection = connection

    def add(self,
            deployment_vnf_stack,
            image_url,
            visibility=IMAGE_VISIBILITY,
            image_parameter_to_update=ConfigurationModifier.IMAGE_PARAMETER,
            disk_format=DEFAULT_DISK_FORMAT):
        # type: (DeploymentVnfStack, str, Optional[str], Optional[str], Optional[str]) -> Union[bool, None, str]
        """ Adds an image to glance from the source specified in image_uri.
        Note that this keyword will update stack's configuration_data with
        image name. It will raise an UploadFail if uploading to glance fails.

        :param deployment_vnf_stack: an instance of DeploymentVnfStack;
               Raises TypeError if configuration_data attribute is
               not initialized. Otherwise, the `image_parameter_to_update`
               key will be filled.
        :param image_url: uri path to image source; should have a
               prefix of "http(s)://" if it's from a remote
               and "file://" if it's from a local storage
        :param visibility: image visibility, can be: 'public' or 'private';
               for specification check the Glance image
               visibility design documentation; defaults to 'public'.
        :param image_parameter_to_update: parameter key to update in vnf
               stack's configuration_data.
        :param disk_format: disk format supported by openstack, defaults to qcow2
         """
        image_name = self._find_image_name(image_url, disk_format)
        logging.debug("Image name is {}".format(image_name))

        images = self.images(name=image_name, status=ImageStatus.ACTIVE)
        image_found = len(images) > 0

        if not image_found:
            log_msg = "{} not found in glance. Downloading..."
            log_msg = log_msg.format(image_name)
            logging.info(log_msg)

            exception_message = "Adding image to glance failed."

            prefix, image_source = self._find_image_source(image_url)
            if prefix == "file":
                logging.warning("Passing file path to `image_url` argument is deprecated. Instead please use:\n"
                                "for robot framework `add_image_from_file` keyword,\n"
                                "for python interface `Image.add_from_file`.")
                uploaded_image = self._upload_image(
                    image_name, image_source, visibility, disk_format)
                response_status = uploaded_image.status
                image_id = uploaded_image.id

                if response_status != self.IMAGE_STATUS_SUCCESS:
                    raise UploadFail(exception_message)

            else:
                status_response_data = self._send_image(
                    image_name, image_url, visibility, disk_format)
                response_status = status_response_data['status']
                image_id = status_response_data['result']['image_id']
                if 'message' in status_response_data:
                    exception_message += " Error message: {}".format(status_response_data['message'])
                if response_status != self.IMAGE_STATUS_SUCCESS:
                    # We should try to remove the image, it can be stuck
                    # with "SAVING" status
                    self._remove_image_and_raise(
                        image_id, disk_format, UploadFail, exception_message)

        else:
            image_id = images[0].id
            logging.info("Image found in glance")

        self._save_env_with_image(deployment_vnf_stack,
                                  image_id,
                                  image_parameter_to_update)

        self._handle_filled_configuration_data(deployment_vnf_stack,
                                               image_id,
                                               image_parameter_to_update)

        return image_id

    def add_from_file(self,
                      deployment_vnf_stack,
                      image_path,
                      visibility=IMAGE_VISIBILITY,
                      image_parameter_to_update=ConfigurationModifier.IMAGE_PARAMETER,
                      disk_format=DEFAULT_DISK_FORMAT,
                      timeout=600):
        # type: (DeploymentVnfStack, str, Optional[str], Optional[str], Optional[str]) -> Union[bool, None, str]
        """
        Adds an image to glance from the file specified in image_path.
        Note that this keyword will update stack's configuration_data with
        image name.
        Keyword will wait for image ACTIVE status for given timeout (defaults to 600seconds).

        :param deployment_vnf_stack: an instance of DeploymentVnfStack;
               Raises TypeError if configuration_data attribute is
               not initialized. Otherwise, the `image_parameter_to_update`
               key will be filled.
        :param image_path: path to image file; could be relative or absolute
        :param visibility: image visibility, can be: 'public' or 'private';
               for specification check the Glance image
               visibility design documentation; defaults to 'public'.
        :param image_parameter_to_update: parameter key to update in vnf
               stack's configuration_data.
        :param disk_format: disk format supported by openstack, defaults to qcow2
        :param timeout: defaults to 600 seconds
        :raises Timeout: if ACTIVE status not reached within given timeout
         """
        image_name = self._find_image_name(image_path, disk_format)
        logging.debug("Image name is {}".format(image_name))

        images = self.images(name=image_name, status=ImageStatus.ACTIVE)
        image_found = len(images) > 0

        if not image_found:
            log_msg = "{} not found in glance. Downloading..."
            log_msg = log_msg.format(image_name)
            logging.info(log_msg)

            uploaded_image = self._upload_image(
                image_name, image_path, visibility, disk_format)
            image_id = uploaded_image.id

            end = time.time() + timeout
            image_status = self.get_status(image_id)
            while image_status.lower() != ImageStatus.ACTIVE:
                if time.time() > end:
                    exception_message = 'Expected image status not reached within given timeout.'
                    self._remove_image_and_raise(image_id, disk_format, Timeout, exception_message)
                time.sleep(self.CHECK_INTERVAL)
                image_status = self.get_status(image_id)

        else:
            image_id = images[0].id
            logging.info("Image found in glance")

        self._save_env_with_image(deployment_vnf_stack,
                                  image_id,
                                  image_parameter_to_update)

        self._handle_filled_configuration_data(deployment_vnf_stack,
                                               image_id,
                                               image_parameter_to_update)

        return image_id

    def _remove_image_and_raise(self, image_id, disk_format, exception, exception_message):
        try:
            self.remove(image_id, disk_format=disk_format)
        except OSSDKException:
            pass
        except OpenStackCloudException as exc:
            exc_msg = "\nCould not delete an image with id: {}."
            exc_msg += "\nError message: {}"
            exc_msg = exc_msg.format(image_id, exc.message)
            exception_message += exc_msg
        finally:
            raise exception(exception_message)

    def _handle_filled_configuration_data(self, deployment_vnf_stack,
                                          image_name,
                                          image_parameter_to_update):
        if deployment_vnf_stack.configuration_data is not None:
            warn_msg = "Using stack's `configuration_data` attribute is " \
                       "deprecated. Set this attribute to `None` to use the " \
                       "maintained Image.add method."
            logging.warning(warn_msg)

            ConfigurationModifier.update_image_name(
                deployment_vnf_stack.configuration_data,
                image_name,
                image_parameter_to_update)

    def _save_env_with_image(self, deployment_vnf_stack, image_name,
                             image_parameter_to_update):
        dict_with_image = {}
        ConfigurationModifier.update_image_name(
            dict_with_image,
            image_name,
            image_parameter_to_update)

        new_path = save_dict_as_yaml(
            dict_with_image, prefix=image_parameter_to_update + "_updated")
        PreparedEnvironments.add_stack_environment(deployment_vnf_stack,
                                                   new_path)

    def upload(self, cbts, image_url, visibility=IMAGE_VISIBILITY, disk_format=DEFAULT_DISK_FORMAT):
        image_name = self._find_image_name(image_url, disk_format=disk_format)
        logging.debug("Image name is {}".format(image_name))
        cbts.heat.bts.image = image_name

        if not self.find(image_name):
            log_msg = "{} not found in glance. Downloading..."
            log_msg = log_msg.format(image_name)
            logging.info(log_msg)

            prefix, image_source = self._find_image_source(image_url)
            if prefix == "file":
                uploaded_image = self._upload_image(image_name, image_source, visibility, disk_format)
                return uploaded_image.status == self.IMAGE_STATUS_SUCCESS
            else:
                status_response_data = self._send_image(image_name, image_url, visibility, disk_format)
                response_status = status_response_data['status']
                return response_status == self.IMAGE_STATUS_SUCCESS
        else:
            logging.info("Image found in glance")

    def _find_image_name(self, path, disk_format):
        return path[path.rfind("/") + 1:path.rfind(".{}".format(disk_format))]

    def _find_image_source(self, path):
        image_source = path.split("://")
        return image_source

    def _upload_image(self, image_name, image_source, visibility, disk_format):
        with open(image_source, mode='rb') as image_data:
            uploaded_image = self.connection.image.upload_image(
                name=image_name,
                visibility=visibility,
                disk_format=disk_format,
                container_format="bare",
                data=image_data)
        return uploaded_image

    def _send_image(self, image_name, image_url, visibility, disk_format):
        self._check_image_url(image_url)
        glance_endpoint_url = self.connection.image.get_endpoint()
        response = self._send_image_import_task_request(
            glance_endpoint_url,
            image_name, image_url, visibility, disk_format)
        response_data = response.json()
        task_url = self._get_task_url(glance_endpoint_url,
                                      response_data['id'])
        status_response_data = self._wait_until_image_is_created(
            task_url)
        return status_response_data

    def _check_image_url(self, image_url):
        response = self.connection.image.request(image_url, method="HEAD")
        response.raise_for_status()

    def _send_image_import_task_request(self, glance_endpoint_url,
                                        image_name, image_url, visibility, disk_format):
        payload = {"type": "import",
                   "input": {"import_from": image_url,
                             "import_from_format": disk_format,
                             "image_properties": {
                                 "name": image_name,
                                 "container_format": "bare",
                                 "disk_format": disk_format,
                                 "visibility": visibility}
                             }
                   }
        tasks_url = glance_endpoint_url + "tasks"
        response = self.connection.session.post(tasks_url, json=payload)
        return response

    def _get_task_url(self, glance_endpoint_url, task_id):
        task_url = glance_endpoint_url + "tasks/" + task_id
        return task_url

    def _wait_until_image_is_created(self, task_url):
        status_response_data = self._get_task_status(task_url)
        while status_response_data['status'] in ['processing', 'pending']:
            time.sleep(self.CHECK_INTERVAL)
            status_response_data = self._get_task_status(task_url)
        return status_response_data

    def _get_task_status(self, task_url):
        status_response = self.connection.session.get(task_url)
        return status_response.json()

    def get_status(self, name_or_id):
        # type: (str) -> str
        image = self.find(name_or_id)
        if not image:
            raise ImageNotFound(name_or_id)
        return image.status.upper()

    def get_name(self, name_or_id):
        # type: (str) -> str
        image = self.find(name_or_id)
        if not image:
            raise ImageNotFound(name_or_id)
        return image.name

    def get_id_by_name(self, name):
        # type: (str) -> str
        image = self.find(name)
        if image:
            if image.id == name:
                logging.info('Image that was found has the same ID as the '
                             'NAME that was passed.')
        else:
            raise ImageNotFound(name)
        return image.id

    def _get_id_of_active_image_by_name_ignoring_ambiguous(self, name):
        images = self.images(name=name, status=ImageStatus.ACTIVE)
        if len(images) > 0:
            return images[0].id
        else:
            raise ImageNotFound(name)

    def does_image_exist(self, name_or_id):
        # type: (str) -> bool
        if self.find(name_or_id):
            return True
        return False

    def remove(self, name_or_id, disk_format=DEFAULT_DISK_FORMAT):
        # type: (str, Optional[str]) -> None
        name = name_or_id.split("/")[-1]
        matches = re.findall("(.*)\." + disk_format + "$", name)
        name_without_ext = name if matches == [] else matches[0]

        logging.debug("Removing image {} from glance...".format(name))

        image = self.find(name_without_ext)
        self.connection.image.delete_image(image, ignore_missing=False)

    def find(self, name_or_id):
        # type: (str) -> OpenstackImage
        try:
            image = self.connection.image.find_image(name_or_id)
        except SDKException as e:
            raise OSSDKException(e.message)
        return image

    def protect(self, name_or_id):
        # type: (str) -> None
        self._set_protected_state(name_or_id, protected=True)

    def unprotect(self, name_or_id):
        # type: (str) -> None
        self._set_protected_state(name_or_id, protected=False)

    def _set_protected_state(self, name_or_id, protected):
        image = self.find(name_or_id)
        self.connection.image.update_image(image, protected=protected)

    def add_tag(self, name_or_id, tag):
        # type: (str, str) -> None
        image = self.find(name_or_id)
        self.connection.image.add_tag(image, tag)

    def remove_tag(self, name_or_id, tag):
        # type: (str, str) -> None
        image = self.find(name_or_id)
        self.connection.image.remove_tag(image, tag)

    def images(self, **attributes):
        # type: (**str) -> List[ImageData]
        found_images = self.connection.image.images(**attributes)
        return [ImageData(status=img.status, id=img.id, name=img.name)
                for img in found_images]

    def _get_status_with_deleted_if_missing(self, name_or_id):
        found_image = self.find(name_or_id)
        if found_image is None:
            image_status = ImageStatus.DELETED
        else:
            image_status = found_image.status
        return image_status

    def wait_for_status(self, name_or_id, status, timeout):
        # type: (str, str,  Union[str, float, int]) -> None
        actual_status = None
        end = time.time() + timeout

        while time.time() < end:
            actual_status = self._get_status_with_deleted_if_missing(name_or_id)
            if actual_status == status:
                break
            time.sleep(self.CHECK_INTERVAL)

        if actual_status != status:
            exc_msg = "Image '{}' did not receive '{}' status after " \
                      "{} second(s). Actual status: '{}'."
            exc_msg = exc_msg.format(
                name_or_id,
                status,
                timeout,
                actual_status)
            raise Timeout(exc_msg)
